def _unique_value(model, field, name, max_length):
    """Historical models skip custom save methods, so unique codes are explicit."""
    base = (slugify(name).upper() or "ITEM")[:max_length]
    candidate = base
    suffix = 2
    while model.objects.filter(**{field: candidate}).exists():
        tail = f"-{suffix}"
        candidate = f"{base[:max_length - len(tail)]}{tail}"
        suffix += 1
    return candidate


def populate_public_library(apps, schema_editor):
    Framework = apps.get_model("curriculum", "CurriculumFramework")
    Level = apps.get_model("curriculum", "EducationLevel")
    Area = apps.get_model("curriculum", "LearningArea")
    Publisher = apps.get_model("content", "Publisher")
    Subject = apps.get_model("institutions", "Subject")
    Collection = apps.get_model("content", "ResourceCollection")
    Book = apps.get_model("content", "DigitalTextbook")
    Resource = apps.get_model("content", "ContentResource")

    framework = Framework.objects.filter(code="CBC").first()
    if framework is None:
        return
    level, _ = Level.objects.get_or_create(
        framework=framework,
        code="SEN",
        defaults={"name": "Senior School", "sequence": 2},
    )
    area_by_name = {}
    for name, code in [
        ("Mathematics", "MATH"),
        ("Integrated Science", "SCI"),
        ("Social Studies", "SOC"),
        ("Computing", "COMP"),
        ("Agriculture", "AGRI"),
        ("Creative Arts", "ARTS"),
    ]:
        area, _ = Area.objects.get_or_create(
            level=level,
            code=code,
            defaults={"name": name, "sequence": len(area_by_name) + 1},
        )
        area_by_name[name] = area
    subject_by_name = {
        item.name: item for item in Subject.objects.filter(name__in=area_by_name)
    }

    for item in BOOK_UPDATES:
        publisher = Publisher.objects.filter(name=item["publisher"]).first()
        if publisher is None:
            publisher = Publisher.objects.create(
                name=item["publisher"],
                code=_unique_value(Publisher, "code", item["publisher"], 50),
            )
        Book.objects.filter(pk=item["id"]).update(
            title=item["title"],
            subtitle=item["subtitle"],
            publisher=publisher,
            subject=subject_by_name.get(item["subject"]),
            education_level=level,
            isbn=item["isbn"],
            description=item["description"],
            cover_image=f"/images/library/covers/{item['cover']}",
            license_type="OPEN",
        )

    for pk, title, resource_type, publisher_name, area_name, collection_name, thumb, url, keyword in RESOURCE_UPDATES:
        publisher = Publisher.objects.filter(name=publisher_name).first()
        if publisher is None:
            publisher = Publisher.objects.create(
                name=publisher_name,
                code=_unique_value(Publisher, "code", publisher_name, 50),
            )
        collection = Collection.objects.filter(name=collection_name).first()
        if collection is None:
            collection = Collection.objects.create(
                name=collection_name,
                slug=_unique_value(Collection, "slug", collection_name, 160).lower(),
            )
        Resource.objects.filter(pk=pk).update(
            title=title,
            description=(
                f"Curated {keyword.lower()} material from {publisher_name}. "
                "Opens the provider's public page in a new tab."
            ),
            resource_type=resource_type,
            delivery="LINK",
            file="",
            thumbnail_image=f"/images/library/thumbnails/{thumb}",
            external_url=url,
            embed_provider=None,
            embed_source_url="",
            education_level=level,
            learning_area=area_by_name.get(area_name),
            subject=subject_by_name.get(area_name),
            collection=collection,
            keywords=[keyword, publisher_name, "open education"],
            offline_available=False,
            size_kb=0,
            status="PUBLISHED",
            published_at=timezone.now(),
            access_scope="PUBLIC",
        )


